// Corner - estimating your sleep need from the sleep log and the 1-10 check-ins.
using System;
using System.Collections.Generic;
using System.Linq;

namespace Corner
{
    /// Works out how much sleep you seem to need: the amount beyond which more sleep stops raising your check-in scores.
    /// It only ever suggests a figure; the Need setting changes when you accept it. Everything tunable is here.
    public static class NeedEstimate
    {
        public const int WindowDays = 60;       // only days this recent are used
        public const int MinDays = 14;          // days needed before anything is suggested...
        public const int MinPerDay = 2;         // ...each with an entered night and at least this many check-ins
        public const int MinEachSide = 3;       // days needed both below the estimate and at or above it
        public const double Sigma = 1.5;        // hours; how widely scores are pooled to find what is normal for a time of day
        public static readonly double[] NightWeights = { 0.5, 0.3, 0.2 }; // how much last night, the night before and the one before that count
        public const double From = 6.0, To = 10.0, Step = 0.25; // the amounts of sleep that are tried
        public const double Floor = 7.0;        // never suggests less: people short on sleep for weeks rate themselves fresher than they are
        public const double MaxRange = 1.5;     // hours; if the likely range is wider than this, nothing is suggested
        public const double MinFit = 0.15;      // share of the day-to-day differences in your scores that sleep must explain
        // How wide the likely range is drawn (3.84 = about 19 chances in 20; 6.63 = 99 in 100). The upper end is the
        // stricter one: suggesting too little sleep is the costlier mistake, so "you may need more" is ruled out last.
        public const double RangeChiLow = 3.84, RangeChiHigh = 6.63;

        public class Result
        {
            public bool Ready;              // there is a figure to suggest
            public double Need, Low, High;  // the figure and its likely range, hours
            public int Days;                // days that could be used
            public string Note;             // one line saying where things stand
        }

        static string Dur(double hours)
        {
            int m = (int)Math.Round(hours * 60);
            return m / 60 + "h" + (m % 60 > 0 ? " " + m % 60 + "m" : "");
        }

        /// One point per usable day: recent sleep (hours) and how fresh you felt that day compared with your usual
        /// for the same hours since waking (points on the 1-10 scale).
        static List<double[]> DayPoints(IList<Night> nights, IList<Feedback.Entry> checks, DateTime now)
        {
            var byDay = new Dictionary<DateTime, Night>();
            foreach (var n in (nights ?? new List<Night>()).Where(x => x != null && x.Valid).OrderBy(x => x.WokeAt)) byDay[n.WokeAt.Date] = n;
            var rated = (checks ?? new List<Feedback.Entry>()).Where(x => x.Score > 0 && x.At <= now && (now - x.At).TotalDays <= WindowDays).ToList();

            Func<double, double> usual = t =>
            {
                double w = 0, sum = 0;
                foreach (var x in rated) { double k = Math.Exp(-(t - x.SinceWake) * (t - x.SinceWake) / (2 * Sigma * Sigma)); w += k; sum += k * x.Score; }
                return sum / w;
            };

            var days = new List<double[]>();
            foreach (var g in rated.GroupBy(x => SleepLog.Today(x.At)))
            {
                Night last;
                if (g.Count() < MinPerDay || !byDay.TryGetValue(g.Key, out last) || last.Assumed) continue; // an assumed night is not a measurement
                double w = 0, sleep = 0;
                for (int k = 0; k < NightWeights.Length; k++)
                {
                    Night n;
                    if (!byDay.TryGetValue(g.Key.AddDays(-k), out n) || n.Assumed) continue;
                    sleep += NightWeights[k] * (k == 0 ? n.Hours : n.TotalHours); // earlier days count their naps; today's come after the fact
                    w += NightWeights[k];
                }
                days.Add(new[] { sleep / w, g.Average(x => x.Score - usual(x.SinceWake)) });
            }
            return days;
        }

        public static Result Build(IList<Night> nights, IList<Feedback.Entry> checks, DateTime now)
        {
            var r = new Result();
            var days = DayPoints(nights, checks, now);
            int n = r.Days = days.Count;
            if (n < MinDays)
            {
                r.Note = "Corner can suggest your sleep need once " + MinDays + " days have an entered night and " + MinPerDay + " check-ins. " + n + " so far.";
                return r;
            }

            double my = days.Average(d => d[1]), total = days.Sum(d => (d[1] - my) * (d[1] - my));
            if (total < 1e-9) { r.Note = "Your check-in scores are all alike, so they say nothing about your sleep need yet."; return r; }

            // For each candidate: scores rise with sleep up to it and are level beyond it. The best candidate leaves the least unexplained.
            var tried = new List<double[]>(); // { candidate, what is left unexplained }
            for (double c = From; c <= To + 1e-9; c += Step)
            {
                var x = days.Select(d => Math.Min(d[0], c)).ToArray();
                double mx = x.Average(), sxx = 0, sxy = 0;
                for (int i = 0; i < n; i++) { sxx += (x[i] - mx) * (x[i] - mx); sxy += (x[i] - mx) * (days[i][1] - my); }
                double left = sxx < 1e-9 || sxy <= 0 ? total : total - sxy * sxy / sxx; // more sleep never counts as making you less fresh
                tried.Add(new[] { c, left });
            }
            double least = tried.Min(t => t[1]);
            var bestRun = tried.Where(t => t[1] <= least * (1 + 1e-9) + 1e-12).Select(t => t[0]).ToList();
            double best = Math.Round((bestRun.First() + bestRun.Last()) / 2 / Step) * Step;

            if (1 - least / total < MinFit) { r.Note = "Over " + n + " days your check-in scores do not yet follow how much you slept, so no sleep need is suggested."; return r; }
            int below = days.Count(d => d[0] < best - 1e-9), atOrAbove = n - below;
            if (atOrAbove < MinEachSide)
            {
                r.Note = "You feel fresher the more you sleep, and Corner has not yet seen where that stops: you may need more than you have been getting. A few longer nights would show it.";
                return r;
            }
            if (below < MinEachSide) { r.Note = "You have rarely slept little enough for Corner to see where your sleep need lies. Nothing is suggested."; return r; }

            double low = tried.Where(t => t[1] <= least * Math.Exp(RangeChiLow / n)).Min(t => t[0]);
            double high = tried.Where(t => t[1] <= least * Math.Exp(RangeChiHigh / n)).Max(t => t[0]);
            if (high - low > MaxRange)
            {
                r.Note = "Your check-ins point to a sleep need somewhere between " + Dur(low) + " and " + Dur(high) + ": not narrow enough to suggest a figure yet.";
                return r;
            }
            r.Need = Math.Max(Floor, best); r.Low = Math.Max(Floor, low); r.High = Math.Max(r.Need, high);
            r.Ready = true;
            r.Note = "From " + n + " days of check-ins: a sleep need of about " + Dur(r.Need) + (r.High - r.Low > 0.01 ? " (likely " + Dur(r.Low) + " to " + Dur(r.High) + ")" : "") + ".";
            return r;
        }
    }
